SELECT CASE WHEN price >= 910 THEN 'high' WHEN price >= 510 THEN 'mid' ELSE 'low' END AS price_bucket, category, SUM(CASE WHEN category = 'Home' THEN stock_qty ELSE 0 END) AS home_stock_qty, MAX(launch_date) AS latest_launch_date, MIN(launch_date) AS first_launch_date FROM products WHERE price > 1190 GROUP BY CASE WHEN price >= 910 THEN 'high' WHEN price >= 510 THEN 'mid' ELSE 'low' END, category ORDER BY price_bucket;
